func (this *Tree) sendMouseEvent_(nsEvent *cocoa.NSEvent, type_ int32, send bool) bool {
	if type_ == DragDetect {
		this.dragDetected = true
	} else {
		if type_ == MouseUp {
			if this.selectedRowIndex != -1 {
				if this.dragDetected {
					this.selectedRowIndex = -1
				} else {
					var widget *cocoa.NSOutlineView = castcocoaNSViewTococoaNSOutlineView(this.View)
					var selectedRows *cocoa.NSIndexSet = widget.SelectedRowIndexes()
					var count int32 = int32(selectedRows.Count())
					var indexBuffer []int64 = make([]int64, count)
					selectedRows.GetIndexes(indexBuffer, int64(count), int64(0))
					for i := int32(0); i < count; i++ {
						if indexBuffer[i] == int64(this.selectedRowIndex) {
							continue
						}
						this.ignoreSelect = true
						widget.DeselectRow(indexBuffer[i])
						this.ignoreSelect = false
					}
					var event *Event = NewEvent()
					var itemID *cocoa.Id = widget.ItemAtRow(int64(this.selectedRowIndex))
					if itemID != (nil) {
						var item *Widget = this.display.GetWidget(itemID.Id)
						_, ok527 := isWidgetToTreeItem(item)
						if item != (nil) && ok527 {
							event.Item = this.display.GetWidget(itemID.Id)
							this.SendSelectionEventEventTypeEventSend(Selection, event, false)
						}
					}
					this.selectedRowIndex = -1
					this.ignoreSelect = true
				}
			}
			this.dragDetected = false
		}
	}
	return this.Composite.sendMouseEvent_(nsEvent, type_, send)
}

