func (this *Tree) SetColumnOrder(order []int32) {
	this.CheckWidget()
	if order == (nil) {
		this.Error(ERROR_NULL_ARGUMENT)
	}
	if this.columnCount == 0 {
		if int32(len(order)) != 0 {
			this.Error(ERROR_INVALID_ARGUMENT)
		}
		return
	}
	if int32(len(order)) != this.columnCount {
		this.Error(ERROR_INVALID_ARGUMENT)
	}
	var oldOrder []int32 = this.GetColumnOrder()
	var reorder bool = false
	var seen []bool = make([]bool, this.columnCount)
	for i := int32(0); i < int32(len(order)); i++ {
		var index int32 = order[i]
		if index < 0 || index >= this.columnCount {
			this.Error(ERROR_INVALID_ARGUMENT)
		}
		if seen[index] {
			this.Error(ERROR_INVALID_ARGUMENT)
		}
		seen[index] = true
		if order[i] != oldOrder[i] {
			reorder = true
		}
	}
	if reorder {
		var outlineView *cocoa.NSOutlineView = castcocoaNSViewTococoaNSOutlineView(this.View)
		var oldX []int32 = make([]int32, int32(len(oldOrder)))
		var check int32
		if (this.style & CHECK) != 0 {
			check = 1
		} else {
			check = 0
		}
		for i := int32(0); i < int32(len(oldOrder)); i++ {
			var index int32 = oldOrder[i]
			oldX[index] = int32(outlineView.RectOfColumn(int64(i + check)).X)
		}
		var newX []int32 = make([]int32, int32(len(order)))
		for i := int32(0); i < int32(len(order)); i++ {
			var index int32 = order[i]
			var column *TreeColumn = this.columns[index]
			var oldIndex int32 = this.IndexOf(column.nsColumn)
			var newIndex int32 = i + check
			outlineView.MoveColumn(int64(oldIndex), int64(newIndex))
			newX[index] = int32(outlineView.RectOfColumn(int64(newIndex)).X)
		}
		var newColumns []*TreeColumn = make([]*TreeColumn, this.columnCount)
		copy(newColumns[0:], this.columns[0:0+this.columnCount])
		for i := int32(0); i < this.columnCount; i++ {
			var column *TreeColumn = newColumns[i]
			if !column.IsDisposed() {
				if newX[i] != oldX[i] {
					column.SendEventEventType(Move)
				}
			}
		}
	}
}

